const { MessageAttachment, Message } = require("discord.js");
const { checkCustomImage } = require("./characters.js");

class charInfo {
    constructor(name, alias, anime, anialias, gender, image, id, rarity) {
        this._name = name;
        this._alias = alias;
        this._anime = anime;
        this._anialias = anialias;
        this._gender = gender;
        this._image = image;
        this._id = id;
        this._rarity = rarity;
    };
    get name() {
        return this._name;
    };
    get alias() {
        return this._alias;
    };
    get anime() {
        return this._anime;
    };
    get anialias() {
        return this._anialias;
    };
    get gender() {
        return this._gender.toUpperCase();
    };
    get image() {
        if (this._image.startsWith("http")) {
            if (this._image.endsWith(".jpg") || this._image.endsWith(".gif") || this._image.endsWith(".webp")) return this._image;
            return this._image + ".png"
        } else {
            if (this._image.endsWith(".jpg") || this._image.endsWith(".gif") || this._image.endsWith(".webp")) return "https://i.ibb.co/" + this._image;
            return "https://i.ibb.co/" + this._image + ".png";
        };
    };
    get id() {
        return this._id;
    };
    get rarity() {
        return this._rarity.toUpperCase();
    };
};

